edits.from:
html(token) {
  return escape(token.text);
},

image({ href, text }) {
  return anchor(href, escape(text));
},

edits.to:
image({ href, text }) {
  return `<img src="${escape(href)}" alt="${escape(text)}">`;
},

edits.from:
if (entry.overheard === true) {
  return { who: `${entry.from} → ${entry.to}`, kind: "overheard", html: html(entry.text), tight: true, ...msg };
}

if (typeof entry.line === "string") {
  return { who: entry.from, kind: "line", text: entry.line, err: entry.err === true, why: entry.why ?? "" };
}
